WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY method ORDER BY amount DESC, id) AS event_seq, AVG(amount) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS amount_avg_3, AVG(amount) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS amount_avg_5, AVG(amount) OVER (PARTITION BY order_id, method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS amount_avg_3_2, RANK() OVER (PARTITION BY order_id ORDER BY amount DESC) AS amount_rank FROM payments) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END) AS refunded_count, SIZE(COLLECT_SET(status)) AS num_status FROM scored GROUP BY DATE_TRUNC('YEAR', paid_at) ORDER BY num_status DESC;
